import{_ as t,o as a,c as i,a2 as o}from"./chunks/framework.BXzK3EA4.js";const d=JSON.parse('{"title":"SSH Public Key Management Guide","description":"","frontmatter":{"title":"SSH Public Key Management Guide"},"headers":[],"relativePath":"operations-knowledge-base/vps/ssh-public-key-management-guide.md","filePath":"operations-knowledge-base/vps/ssh-public-key-management-guide.md","lastUpdated":1794309341000}'),n={name:"operations-knowledge-base/vps/ssh-public-key-management-guide.md"};function r(s,e,l,h,c,u){return a(),i("div",null,[...e[0]||(e[0]=[o('<h2 id="purpose" tabindex="-1">Purpose <a class="header-anchor" href="#purpose" aria-label="Permalink to &quot;Purpose&quot;">​</a></h2><p>This document explains how to create, import, and manage SSH public keys in the Raksmart Client Portal. It also introduces common use cases for SSH keys, helping you authenticate securely and improve the security of Linux server access.</p><p><strong>Applicable Products:</strong></p><ul><li>Bare Metal Cloud</li><li>VPS</li></ul><hr><h2 id="_1-what-is-an-ssh-public-key" tabindex="-1">1. What is an SSH Public Key? <a class="header-anchor" href="#_1-what-is-an-ssh-public-key" aria-label="Permalink to &quot;1. What is an SSH Public Key?&quot;">​</a></h2><p>SSH Key authentication is a secure authentication method based on a pair of cryptographic keys. Compared with password authentication, SSH Key authentication provides enhanced security.</p><p>An SSH Key pair consists of two parts:</p><ul><li><strong>Public Key</strong> – Stored on the server or in the Raksmart Client Portal for identity verification.</li><li><strong>Private Key</strong> – Stored on your local computer and used to log in to the server.</li></ul><p>During login, the client uses the private key for authentication, while the server verifies the corresponding public key.</p><blockquote><p><strong>Note:</strong></p><p>After creating an SSH key pair, the system automatically downloads the private key file (<strong>id_rsa.pem</strong>). Only the corresponding public key is stored in the Raksmart Client Portal. The private key is <strong>not</strong> stored by the system.</p></blockquote><hr><h2 id="_2-accessing-the-ssh-public-key-management-page" tabindex="-1">2. Accessing the SSH Public Key Management Page <a class="header-anchor" href="#_2-accessing-the-ssh-public-key-management-page" aria-label="Permalink to &quot;2. Accessing the SSH Public Key Management Page&quot;">​</a></h2><ol><li>Log in to the <strong>Raksmart Client Portal</strong>.</li><li>Go to <strong>Member Center</strong>.</li><li>Click <strong>Technical Support</strong>.</li><li>Select <strong>SSH Public Keys</strong>.</li></ol><p>On this page, you can view, create, import, and manage your SSH public keys.</p><hr><h2 id="_3-adding-an-ssh-public-key" tabindex="-1">3. Adding an SSH Public Key <a class="header-anchor" href="#_3-adding-an-ssh-public-key" aria-label="Permalink to &quot;3. Adding an SSH Public Key&quot;">​</a></h2><p>Click the <strong>Add</strong> button at the top of the page to open the <strong>Add Information</strong> window.</p><p>Before creating a key, choose the method that best suits your needs.</p><blockquote><p><strong>Note:</strong></p><ul><li>If you are using SSH Keys for the first time, it is recommended to select <strong>Create New Key Pair</strong>. The system will automatically generate both the public and private keys.</li><li>If you already have an SSH public key, select <strong>Use Existing Public Key</strong> to import it without generating a new key pair.</li></ul></blockquote><hr><h2 id="_1-name" tabindex="-1">1. Name <a class="header-anchor" href="#_1-name" aria-label="Permalink to &quot;1. Name&quot;">​</a></h2><p>Enter a descriptive name for the SSH key, for example:</p><ul><li>Office-PC</li><li>Laptop</li><li>Linux-Server</li></ul><p>It is recommended to use a meaningful name based on the device or intended purpose for easier management.</p><hr><h2 id="_2-method" tabindex="-1">2. Method <a class="header-anchor" href="#_2-method" aria-label="Permalink to &quot;2. Method&quot;">​</a></h2><p>The following two methods are available:</p><h3 id="method-1-create-new-key-pair-recommended" tabindex="-1">Method 1: Create New Key Pair (Recommended) <a class="header-anchor" href="#method-1-create-new-key-pair-recommended" aria-label="Permalink to &quot;Method 1: Create New Key Pair (Recommended)&quot;">​</a></h3><p>Select <strong>Create New Key Pair</strong>, and the system will automatically generate a new SSH key pair.</p><p>After creation:</p><ul><li>The private key file (<strong>id_rsa.pem</strong>) will be downloaded automatically.</li><li>The corresponding public key will be saved in the Client Portal.</li></ul><blockquote><p><strong>Important:</strong></p><p>The <strong>id_rsa.pem</strong> file is your SSH private key and is available <strong>only once</strong> during creation.</p><p>Please save it securely. If it is lost, it cannot be downloaded again, and you will need to generate a new SSH key pair.</p></blockquote><hr><h3 id="method-2-use-existing-public-key" tabindex="-1">Method 2: Use Existing Public Key <a class="header-anchor" href="#method-2-use-existing-public-key" aria-label="Permalink to &quot;Method 2: Use Existing Public Key&quot;">​</a></h3><p>If you already have an SSH public key, select <strong>Use Existing Public Key</strong>.</p><p>Simply paste the contents of your existing public key into the corresponding input field.</p><blockquote><p><strong>Note:</strong></p><p>Only the public key is required. Do <strong>not</strong> upload your private key.</p></blockquote><hr><h2 id="_3-encryption-method" tabindex="-1">3. Encryption Method <a class="header-anchor" href="#_3-encryption-method" aria-label="Permalink to &quot;3. Encryption Method&quot;">​</a></h2><p>The following encryption algorithms are currently supported:</p><ul><li>ssh-rsa</li><li>ssh-dss</li><li>ecdsa-sha2-nistp521</li><li>ssh-ed25519</li></ul><p>Select the encryption algorithm that best matches your environment.</p><blockquote><p><strong>Recommendation:</strong></p><p><strong>ssh-ed25519</strong> and <strong>ssh-rsa</strong> are recommended due to their broad compatibility and strong security.</p></blockquote><hr><h2 id="_4-submit" tabindex="-1">4. Submit <a class="header-anchor" href="#_4-submit" aria-label="Permalink to &quot;4. Submit&quot;">​</a></h2><p>After confirming that all information is correct, click <strong>Submit</strong> to create the SSH public key.</p><p>If you wish to cancel the operation, click <strong>Close</strong>.</p><hr><h2 id="_4-managing-ssh-public-keys" tabindex="-1">4. Managing SSH Public Keys <a class="header-anchor" href="#_4-managing-ssh-public-keys" aria-label="Permalink to &quot;4. Managing SSH Public Keys&quot;">​</a></h2><p>After an SSH public key has been created, it will appear in the management list.</p><p>You can view information such as:</p><ul><li>Name</li><li>Public Key</li><li>Encryption Algorithm</li><li>Creation Time (if displayed)</li></ul><p>You may also delete SSH public keys that are no longer needed.</p><hr><h2 id="_5-common-use-cases-for-ssh-public-keys" tabindex="-1">5. Common Use Cases for SSH Public Keys <a class="header-anchor" href="#_5-common-use-cases-for-ssh-public-keys" aria-label="Permalink to &quot;5. Common Use Cases for SSH Public Keys&quot;">​</a></h2><p>SSH public keys are primarily used for Linux server authentication.</p><p>You can choose SSH Key authentication in the following scenarios:</p><ul><li>Creating a Bare Metal Cloud instance</li><li>Reinstalling a Linux operating system</li><li>Other products that support SSH Key authentication</li></ul><p>When <strong>SSH Key</strong> is selected as the login method, simply choose one of your existing SSH public keys.</p><p>The system will automatically install the selected public key on the server, enabling SSH Key authentication.</p><blockquote><p><strong>Note:</strong></p><p>After creating an SSH key pair, please refer to <strong>&quot;<a href="/operations-knowledge-base/vps/how-to-use-a-private-key-for-remote-login.html">How to Log In to a Linux Server Using an SSH Private Key</a>&quot;</strong> for instructions on using the downloaded private key (<strong>id_rsa.pem</strong>) to access your server.</p></blockquote><hr><h2 id="_6-frequently-asked-questions" tabindex="-1">6. Frequently Asked Questions <a class="header-anchor" href="#_6-frequently-asked-questions" aria-label="Permalink to &quot;6. Frequently Asked Questions&quot;">​</a></h2><h3 id="q1-what-is-the-id-rsa-pem-file" tabindex="-1">Q1: What is the id_rsa.pem file? <a class="header-anchor" href="#q1-what-is-the-id-rsa-pem-file" aria-label="Permalink to &quot;Q1: What is the id\\_rsa.pem file?&quot;">​</a></h3><p>The <strong>id_rsa.pem</strong> file is the SSH private key generated by the system.</p><p>It is required for SSH authentication and should be stored securely on your local computer. Never share it with others.</p><hr><h3 id="q2-why-can-i-only-see-the-public-key-in-the-client-portal" tabindex="-1">Q2: Why can I only see the public key in the Client Portal? <a class="header-anchor" href="#q2-why-can-i-only-see-the-public-key-in-the-client-portal" aria-label="Permalink to &quot;Q2: Why can I only see the public key in the Client Portal?&quot;">​</a></h3><p>For security reasons, the Client Portal stores <strong>only the public key</strong>.</p><p>The private key is available for download <strong>only once</strong> when the key pair is created and cannot be viewed or downloaded again.</p><hr><h3 id="q3-what-should-i-do-if-i-lose-my-private-key" tabindex="-1">Q3: What should I do if I lose my private key? <a class="header-anchor" href="#q3-what-should-i-do-if-i-lose-my-private-key" aria-label="Permalink to &quot;Q3: What should I do if I lose my private key?&quot;">​</a></h3><p>The private key cannot be recovered.</p><p>If it is lost, you must generate a new SSH key pair and configure the server to use the new public key.</p><hr><h3 id="q4-can-ssh-public-keys-be-used-for-windows-login" tabindex="-1">Q4: Can SSH public keys be used for Windows login? <a class="header-anchor" href="#q4-can-ssh-public-keys-be-used-for-windows-login" aria-label="Permalink to &quot;Q4: Can SSH public keys be used for Windows login?&quot;">​</a></h3><p>SSH public keys are primarily intended for Linux SSH authentication.</p><p>Windows supports SSH Key authentication only if services such as <strong>OpenSSH Server</strong> have been installed and configured.</p><hr><h3 id="q5-when-should-i-use-ssh-key-authentication" tabindex="-1">Q5: When should I use SSH Key authentication? <a class="header-anchor" href="#q5-when-should-i-use-ssh-key-authentication" aria-label="Permalink to &quot;Q5: When should I use SSH Key authentication?&quot;">​</a></h3><p>SSH Key authentication is recommended for:</p><ul><li>Daily Linux server administration</li><li>Automated operations and maintenance</li><li>Managing multiple servers</li><li>Improving login security</li><li>Reducing the risks associated with password-based authentication</li></ul><hr><h2 id="notes" tabindex="-1">Notes <a class="header-anchor" href="#notes" aria-label="Permalink to &quot;Notes&quot;">​</a></h2><p>⚠️ The <strong>id_rsa.pem</strong> private key is available <strong>only once</strong> during creation. Please download and store it securely.</p><p>⚠️ The private key contains sensitive information. Do not share it or upload it to public locations.</p><p>⚠️ The Raksmart Client Portal stores only the public key. The private key cannot be downloaded again.</p><p>⚠️ If the private key is lost, you must create a new SSH key pair and update the server with the new public key.</p><p>⚠️ It is recommended to use <strong>ssh-ed25519</strong> or <strong>ssh-rsa</strong> whenever possible for better compatibility and security.</p><hr>',91)])])}const y=t(n,[["render",r]]);export{d as __pageData,y as default};
